<?php
$mode = $mode ?? 'create';
$device = $device ?? [];
$title = $title ?? ($mode === 'edit' ? 'Edit Installation' : 'Create Installation');
$inventory = $inventory ?? ['trackers' => [], 'fls' => [], 'cameras' => [], 'sims' => []];
$packageTypes = $packageTypes ?? \GPSDevice::packageTypes();
$esc = static fn($value) => htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8');
$package = (string)($device['package_type'] ?? 'Basic');
$needsFls = in_array($package, ['Basic + FLS', 'Basic + FLS + Camera'], true);
$needsCamera = $package === 'Basic + FLS + Camera';
?>
