<div class="col-md-6"><label class="form-label" for="package-type">Package</label><select class="form-select" name="package_type" id="package-type" required><?php foreach ($packageTypes as $type): ?><option value="<?= $esc($type) ?>" <?= $package === $type ? 'selected' : '' ?>><?= $esc($type) ?></option><?php endforeach; ?></select></div>
<div class="col-md-6"><label class="form-label" for="tracker-product">Tracker from inventory</label><select class="form-select" name="tracker_product_id" id="tracker-product" required><option value="">Choose tracker</option><?php foreach ($inventory['trackers'] as $product): ?><option value="<?= (int)$product['id'] ?>" <?= (string)($device['tracker_product_id'] ?? '') === (string)$product['id'] ? 'selected' : '' ?>><?= $esc($product['item_type']) ?> · stock <?= (int)$product['opening_stock'] ?></option><?php endforeach; ?></select></div>
<div class="col-md-6 d-none" id="fls-field"><label class="form-label" for="fls-product">FLS from inventory</label><select class="form-select" name="fls_product_id" id="fls-product" <?= $needsFls ? 'required' : 'disabled' ?>><option value="">Choose FLS</option><?php foreach ($inventory['fls'] as $product): ?><option value="<?= (int)$product['id'] ?>" <?= (string)($device['fls_product_id'] ?? '') === (string)$product['id'] ? 'selected' : '' ?>><?= $esc($product['item_type']) ?> · stock <?= (int)$product['opening_stock'] ?></option><?php endforeach; ?></select><?php if (!$inventory['fls']): ?><div class="form-text">No FLS units in stock.</div><?php endif; ?></div>
<div class="col-md-6 d-none" id="camera-field"><label class="form-label" for="camera-product">Camera from inventory</label><select class="form-select" name="camera_product_id" id="camera-product" <?= $needsCamera ? 'required' : 'disabled' ?>><option value="">Choose camera</option><?php foreach ($inventory['cameras'] as $product): ?><option value="<?= (int)$product['id'] ?>" <?= (string)($device['camera_product_id'] ?? '') === (string)$product['id'] ? 'selected' : '' ?>><?= $esc($product['item_type']) ?> · stock <?= (int)$product['opening_stock'] ?></option><?php endforeach; ?></select><?php if (!$inventory['cameras']): ?><div class="form-text">No cameras in stock.</div><?php endif; ?></div>
<div class="col-md-6"><label class="form-label" for="sim-product">SIM / line from inventory <span class="text-secondary fw-normal">(optional)</span></label><select class="form-select" name="sim_product_id" id="sim-product"><option value="">No SIM / line</option><?php foreach ($inventory['sims'] as $product): ?><option value="<?= (int)$product['id'] ?>" <?= (string)($device['sim_product_id'] ?? '') === (string)$product['id'] ? 'selected' : '' ?>><?= $esc($product['item_type']) ?> · stock <?= (int)$product['opening_stock'] ?></option><?php endforeach; ?></select></div>
