<div class="col-md-6"><label class="form-label" for="tracker-serial">Tracker serial number <span class="text-secondary fw-normal">(optional)</span></label><input class="form-control" id="tracker-serial" name="serial" inputmode="numeric" pattern="[0-9]*" value="<?= $esc($device['serial'] ?? '') ?>"></div>
<div class="col-md-6" id="fls-serial-field"><label class="form-label" for="fls-serial">FLS serial number <span class="text-secondary fw-normal">(optional)</span></label><input class="form-control" id="fls-serial" name="fls_serial" inputmode="numeric" pattern="[0-9]*" value="<?= $esc($device['fls_serial'] ?? '') ?>"></div>
<div class="col-md-6" id="camera-serial-field"><label class="form-label" for="camera-serial">Camera serial number <span class="text-secondary fw-normal">(optional)</span></label><input class="form-control" id="camera-serial" name="camera_serial" inputmode="numeric" pattern="[0-9]*" value="<?= $esc($device['camera_serial'] ?? '') ?>"></div>
<div class="col-md-6"><label class="form-label" for="installed-at">Installation date</label><input class="form-control" id="installed-at" type="date" name="installed_at" value="<?= $esc(isset($device['installed_at']) ? substr((string)$device['installed_at'], 0, 10) : date('Y-m-d')) ?>"></div>
<div class="col-12 d-flex flex-wrap gap-2 pt-2"><button class="btn btn-primary" type="submit"><i class="fa-solid fa-floppy-disk me-2"></i><?= $mode === 'edit' ? 'Update installation' : 'Save installation' ?></button><a class="btn btn-outline-secondary" href="/index.php?controller=gps">Cancel</a></div>
</form></div></div>
<script>
const packageSelect=document.getElementById('package-type'),flsSelect=document.getElementById('fls-product'),cameraSelect=document.getElementById('camera-product');
function syncPackage(){const needsFls=['Basic + FLS','Basic + FLS + Camera'].includes(packageSelect.value),needsCamera=packageSelect.value==='Basic + FLS + Camera';document.getElementById('fls-field').classList.toggle('d-none',!needsFls);document.getElementById('camera-field').classList.toggle('d-none',!needsCamera);document.getElementById('fls-serial-field').classList.toggle('d-none',!needsFls);document.getElementById('camera-serial-field').classList.toggle('d-none',!needsCamera);flsSelect.disabled=!needsFls;flsSelect.required=needsFls;cameraSelect.disabled=!needsCamera;cameraSelect.required=needsCamera;if(!needsFls){flsSelect.value='';document.getElementById('fls-serial').value='';}if(!needsCamera){cameraSelect.value='';document.getElementById('camera-serial').value='';}}
packageSelect.addEventListener('change',syncPackage);syncPackage();
</script>
